import React, { useState } from 'react';
import AddOrder from './components/AddOrder';
import OrderList from './components/OrderList';
import './App.css';

function App() {
  const [refresh, setRefresh] = useState(false);

  const handleOrderAdded = () => {
    setRefresh(!refresh);
  };

  return (
    <div className="App">
      <div className="header">
        <h1>🍕 FoodieHub</h1>
        <h2>Your favorite meals, delivered fresh</h2>
      </div>
      <div className="main-content">
        <div className="form-section">
          <h3 className="form-title">Place Your Order</h3>
          <AddOrder onOrderAdded={handleOrderAdded} />
        </div>
        <div className="orders-section">
          <h3 className="orders-title">Your Orders</h3>
          <OrderList refresh={refresh} />
        </div>
      </div>
      <div className="footer">
        © 2025 FoodieHub. Delivering happiness, one meal at a time. 🚀
      </div>
    </div>
  );
}

export default App;
